request.user_message:
Abstract the following semantic predicate cluster into exactly one reusable predicate.

Cluster ID:
ternary-009

Cluster Arity:
3

Cluster Members:
[
  {
    "name": "CONFIRMS_OUTCOME_AGAINST_PREDICTION",
    "definition": "A reasoning node formulates an expected result before the corresponding execution outcome is observed, the observation reports the actual outcome, and a later reasoning node explicitly compares the actual outcome with the previously stated expectation and states whether they agree.",
    "parameters": [
      {
        "name": "prediction_reasoning",
        "type": "reasoning",
        "description": "The reasoning node stating the expected result before the outcome is observed."
      },
      {
        "name": "outcome_observation",
        "type": "observation",
        "description": "The observation reporting the actual execution outcome."
      },
      {
        "name": "confirmation_reasoning",
        "type": "reasoning",
        "description": "The reasoning node comparing the actual outcome with the previously stated expectation and stating agreement or disagreement."
      }
    ],
    "assertion_conditions": [
      "The prediction reasoning states at least one expected value or result derived independently of the execution being predicted, before that execution's outcome is observed.",
      "The outcome observation reports the actual result produced by the execution.",
      "The confirmation reasoning explicitly compares the actual outcome to the previously stated expectation and states agreement or disagreement."
    ],
    "exclusion_conditions": [
      "No expectation is stated before the outcome is observed.",
      "The confirmation reasoning restates the observed result without comparing it to a previously stated expectation.",
      "The expected result and the observed outcome are not comparable quantities.",
      "The expectation is only formulated after seeing the outcome, so it cannot serve as an advance prediction."
    ]
  },
  {
    "name": "REVISES_HYPOTHESIS_USING_CONTRADICTING_OBSERVATION",
    "definition": "A previously stated expectation, hypothesis, or interpretation is replaced or corrected after an observation reports a result incompatible with it, with the revised reasoning explicitly incorporating that contradictory evidence as the reason for the change.",
    "parameters": [
      {
        "name": "prior_reasoning",
        "type": "reasoning",
        "description": "The earlier reasoning node stating the expectation, hypothesis, or interpretation that is being revised."
      },
      {
        "name": "contradicting_observation",
        "type": "observation",
        "description": "The observation reporting a result, error, or measured value that does not match the prior expectation."
      },
      {
        "name": "revised_reasoning",
        "type": "reasoning",
        "description": "The later reasoning node that corrects or replaces the prior expectation in light of the contradicting observation."
      }
    ],
    "assertion_conditions": [
      "The prior reasoning asserts a specific expectation, hypothesis, structural assumption, or interpretation that is identifiable.",
      "The observation reports a result or error that is incompatible with that prior expectation.",
      "The revised reasoning changes or corrects the prior expectation and refers to the conflicting result as the reason for the change."
    ],
    "exclusion_conditions": [
      "No prior expectation or hypothesis is identifiable in the earlier reasoning.",
      "The observation adds information without contradicting the prior expectation.",
      "The revision is unrelated to the observed evidence, or the prior expectation is merely restated unchanged.",
      "The earlier statement is only a plan of action rather than an expectation or interpretation that could be contradicted."
    ]
  }
]

